-- Small training organizations serialize timetable/attendance writes per organization.
-- This makes cross-class teacher/room/student checks atomic, including the first schedule.
CREATE TABLE edu_schedule_lock (organization_id VARCHAR(32) NOT NULL PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_class (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, name VARCHAR(100) NOT NULL, mode VARCHAR(10) NOT NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_class_org (organization_id,id), CHECK (mode IN ('HOURS','EVENT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_membership (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, class_id VARCHAR(32) NOT NULL, enrollment_id VARCHAR(32) NOT NULL, effective_from BIGINT NOT NULL, effective_to BIGINT NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_membership (organization_id,class_id,enrollment_id), FOREIGN KEY (organization_id,class_id) REFERENCES edu_class (organization_id,id), FOREIGN KEY (organization_id,enrollment_id) REFERENCES edu_enrollment (organization_id,id), CHECK (effective_to IS NULL OR effective_to>effective_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_session (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, class_id VARCHAR(32) NOT NULL, request_key VARCHAR(64) NOT NULL, teacher_id VARCHAR(32) NOT NULL, room_key VARCHAR(32) NOT NULL, starts_at BIGINT NOT NULL, ends_at BIGINT NOT NULL, status VARCHAR(20) NOT NULL, makeup_for_session_id VARCHAR(32) NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_session_org (organization_id,id), UNIQUE KEY uk_edu_session_request (organization_id,request_key), KEY idx_edu_session_time (organization_id,starts_at,ends_at), FOREIGN KEY (organization_id,class_id) REFERENCES edu_class (organization_id,id), FOREIGN KEY (organization_id,makeup_for_session_id) REFERENCES edu_session (organization_id,id), CHECK (ends_at>starts_at), CHECK (status IN ('SCHEDULED','CANCELLED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_session_student (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, session_id VARCHAR(32) NOT NULL, enrollment_id VARCHAR(32) NOT NULL, student_id VARCHAR(32) NOT NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_session_student (organization_id,session_id,student_id), FOREIGN KEY (organization_id,session_id) REFERENCES edu_session (organization_id,id), FOREIGN KEY (organization_id,enrollment_id) REFERENCES edu_enrollment (organization_id,id), FOREIGN KEY (organization_id,student_id) REFERENCES edu_student (organization_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_attendance (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, session_id VARCHAR(32) NOT NULL, enrollment_id VARCHAR(32) NOT NULL, status VARCHAR(10) NOT NULL, charged_units DECIMAL(10,2) NOT NULL, revision INT NOT NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_attendance (organization_id,session_id,enrollment_id), FOREIGN KEY (organization_id,session_id) REFERENCES edu_session (organization_id,id), FOREIGN KEY (organization_id,enrollment_id) REFERENCES edu_enrollment (organization_id,id), CHECK (charged_units>=0), CHECK (status IN ('PRESENT','ABSENT','LEAVE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_attendance_event (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, attendance_id VARCHAR(32) NOT NULL, request_key VARCHAR(64) NOT NULL, request_payload TEXT NOT NULL, revision INT NOT NULL, previous_status VARCHAR(10) NULL, status VARCHAR(10) NOT NULL, reason VARCHAR(1000) NOT NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_attendance_request (organization_id,request_key), FOREIGN KEY (attendance_id) REFERENCES edu_attendance (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE edu_credit_entry (
    id VARCHAR(32) PRIMARY KEY, organization_id VARCHAR(32) NOT NULL, enrollment_id VARCHAR(32) NOT NULL, session_id VARCHAR(32) NULL, operation_key VARCHAR(128) NOT NULL, kind VARCHAR(20) NOT NULL, units DECIMAL(10,2) NOT NULL, create_user VARCHAR(32) NOT NULL, update_user VARCHAR(32) NOT NULL, create_time BIGINT NOT NULL, update_time BIGINT NOT NULL, UNIQUE KEY uk_edu_credit_operation (organization_id,operation_key), FOREIGN KEY (organization_id,enrollment_id) REFERENCES edu_enrollment (organization_id,id), FOREIGN KEY (organization_id,session_id) REFERENCES edu_session (organization_id,id), CHECK (kind IN ('GRANT','DEBIT','REVERSAL')), CHECK ((kind='DEBIT' AND units<0) OR (kind IN ('GRANT','REVERSAL') AND units>0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
-- Preserve any handoffs made before the ledger migration.
INSERT INTO edu_credit_entry (id,organization_id,enrollment_id,operation_key,kind,units,create_user,update_user,create_time,update_time)
SELECT id,organization_id,id,CONCAT('grant:',id),'GRANT',total_units,create_user,update_user,create_time,update_time FROM edu_enrollment WHERE status='ACTIVE';
